<script setup lang="ts">
import {inbox} from '../workInbox'
import {computed,onBeforeUnmount,onMounted,ref,watch} from 'vue'
import {RouterLink,useRoute} from 'vue-router'
import {session} from '../session'
import DataListControls from '../components/DataListControls.vue'
import PaginationBar from '../components/PaginationBar.vue'
import BusinessDialog from '../components/BusinessDialog.vue'
import BusinessHistory from '../components/BusinessHistory.vue'
import CustomerReceiptForm from '../components/CustomerReceiptForm.vue'
import CustomerReceiptReviewAction from '../components/CustomerReceiptReviewAction.vue'
import ModulePageNav from '../components/ModulePageNav.vue'
import { receiptList, reviewReceipt, resubmitReceipt, businessAccounts, receiptLabels, channelLabels, purposeLabels, money, businessTime } from '../customerBusinessApi'

import type {Receipt,BusinessAccount} from '../customerBusinessApi'
import '../salesBusiness.css'
import { useFinanceReviewPolicy } from '../financeReviewPolicy'
const route=useRoute();const actor=computed(()=>session.bootstrap?.actor),access=computed(()=>session.bootstrap?.staff_access)
const finance=computed(()=>!!actor.value&&['platform_admin','staff','sales_staff'].includes(actor.value.role)&&(actor.value.role==='platform_admin'||access.value?.is_super_admin||access.value?.permissions.includes('finance.dashboard.view')))
const { policyReady, policyError, requireDistinctReviewer, refreshPolicy } = useFinanceReviewPolicy(computed(() => Boolean(finance.value)))
const canReview=computed(()=>finance.value&&(access.value?.is_super_admin||access.value?.permissions.includes('finance.recharge.approve')))
const canSubmit=computed(()=>!finance.value||access.value?.is_super_admin||access.value?.permissions.includes('finance.recharge.create'))
const tenant=computed(()=>Number(route.query.tenant||0));const tab=ref('receipts'),items=ref<Receipt[]>([]),accounts=ref<BusinessAccount[]>([])
const search=ref(''),status=ref('all'),channel=ref('all'),view=ref<'card'|'table'>('table'),page=ref(1),size=ref(12),total=ref(0),pages=ref(1),loading=ref(false),error=ref(''),notice=ref('')
const states=Object.entries(receiptLabels).filter(([v])=>['pending','needs_info','posting_failed','rejected','posted'].includes(v)).map(([value,label])=>({value,label}));states.unshift({value:'all',label:'全部收款状态'})
let c:AbortController|undefined,timer:ReturnType<typeof setTimeout>|undefined,poll:ReturnType<typeof setInterval>|undefined
const mode=ref(''),target=ref<Receipt|null>(null),formTenant=ref(0),action=ref('post'),note=ref(''),confirmed=ref(false),saving=ref(false),formError=ref('')
async function load(silent=false){c?.abort();const a=new AbortController();c=a;if(!silent)loading.value=true;error.value='';try{const r=await (tab.value==='accounts'?businessAccounts({search:search.value,qualification:'unconfirmed',page:page.value,page_size:size.value},a.signal):receiptList({tenant_id:tenant.value||undefined,search:search.value,status:status.value,channel:channel.value,page:page.value,page_size:size.value},a.signal));if(a.signal.aborted)return;if(tab.value==='accounts')accounts.value=r.items as BusinessAccount[];else items.value=r.items as Receipt[];total.value=r.total;pages.value=Math.max(1,r.total_pages);if(page.value>pages.value)page.value=pages.value}catch(e){if(!a.signal.aborted)error.value=e instanceof Error?e.message:'读取失败'}finally{if(c===a)loading.value=false}}
function first(){if(page.value!==1)page.value=1;else void load()}
watch([status,channel,size,tab,tenant],first);watch(page,()=>load());watch(search,()=>{clearTimeout(timer);timer=setTimeout(first,300)})
function refreshOnInbox(){if(!document.hidden&&!mode.value&&!loading.value)void load(true)}
onMounted(()=>{void load();window.addEventListener('work-inbox-updated',refreshOnInbox);poll=setInterval(()=>{if(actor.value?.role==='customer'||inbox.error)refreshOnInbox()},60000)});onBeforeUnmount(()=>{c?.abort();clearTimeout(timer);clearInterval(poll);window.removeEventListener('work-inbox-updated',refreshOnInbox)})
function submitFor(id=tenant.value){formTenant.value=id;mode.value='submit';formError.value=''}
function open(v:Receipt,m:string){target.value=v;mode.value=m;note.value='';confirmed.value=false;action.value='post';formError.value=''}
async function save(){if(!target.value||saving.value||(mode.value==='review'&&(!confirmed.value||!policyReady.value||!canReview.value||(requireDistinctReviewer.value&&(target.value.requester_user_id===actor.value?.user_id||target.value.last_submitter_user_id===actor.value?.user_id)))))return;saving.value=true;formError.value='';try{if(mode.value==='review')await reviewReceipt(target.value,action.value,note.value);else await resubmitReceipt(target.value,note.value);mode.value='';notice.value='处理已保存。仅财务成功入账才认定真实客户。';await load()}catch(e){formError.value=(e instanceof Error?e.message:'处理失败')+'；请关闭后重新打开该单据核对最新状态。';confirmed.value=false;await load(true)}finally{saving.value=false}}
</script>
<template><div class="management-page sales-business customer-receipts-page"><ModulePageNav v-if="finance" hub="finance" active-title="客户收款确认"/><header class="sb-toolbar"><div><h2>{{finance?'客户收款确认':'收款进度'}}</h2></div><div class="sb-actions"><RouterLink v-if="finance && (access?.is_super_admin || actor?.role==='platform_admin')" class="receipt-policy-link" to="/system/settings#finance-review-policy">配置审核规则</RouterLink><button @click="load()">刷新</button><button v-if="canSubmit" class="primary" @click="submitFor()">提交收款资料</button></div></header><p v-if="finance && policyError" class="receipt-policy-status" role="alert">{{policyError}} <button type="button" @click="refreshPolicy">重新读取规则</button></p><p v-if="notice" class="sb-success">{{notice}}</p><section class="sb-panel"><div v-if="finance" class="sb-actions"><button :class="{primary:tab==='receipts'}" @click="tab='receipts'">收款单与待办</button><button :class="{primary:tab==='accounts'}" @click="tab='accounts'">未确认客户（不是已收款）</button></div><DataListControls v-model:view-mode="view" v-model:search="search" v-model:status="status" v-model:page-size="size" :status-options="tab==='receipts'?states:[]" search-placeholder="客户名称或收款单号"/><label v-if="tab==='receipts'">渠道 <select v-model="channel"><option value="all">全部渠道</option><option value="bank_transfer">转账</option><option value="offline">线下收款</option><option value="platform">平台支付</option></select></label><p v-if="error" class="sb-error" role="alert">{{error}} <button @click="load()">重试</button></p><p v-else-if="loading" class="sb-empty">读取中…</p><template v-else-if="tab==='accounts'"><div v-if="view==='table'" class="sb-table"><table><thead><tr><th>客户</th><th>认定</th><th>开户时间</th><th>操作</th></tr></thead><tbody><tr v-for="v in accounts" :key="v.tenant_id"><td>{{v.name}}<small>@{{v.username}} · #{{v.tenant_id}}</small></td><td>待财务确认</td><td>{{businessTime(v.created_at)}}</td><td><button v-if="canSubmit" @click="submitFor(v.tenant_id)">提交收款资料</button><RouterLink :to="'/staff/finance/customers/'+v.tenant_id+'/money'">资金记录</RouterLink></td></tr></tbody></table></div><div v-else class="sb-grid"><article v-for="v in accounts" :key="v.tenant_id" class="sb-record"><h3>{{v.name}}</h3><p>已开户，待财务确认</p><small>@{{v.username}} · {{businessTime(v.created_at)}}</small><div class="sb-actions"><button v-if="canSubmit" @click="submitFor(v.tenant_id)">提交收款资料</button></div></article></div></template><template v-else><p v-if="!items.length" class="sb-empty">暂无收款记录</p><div v-else-if="view==='table'" class="sb-table"><table><thead><tr><th>客户 / 收款单</th><th>用途 / 渠道</th><th>申报实收金额</th><th>审核状态</th><th>提交 / 入账时间</th><th>操作</th></tr></thead><tbody><tr v-for="v in items" :key="v.id"><td><strong>{{v.customer_name}}</strong><small>{{v.receipt_no}}</small></td><td>{{purposeLabels[v.purpose]}}<small>{{channelLabels[v.channel]}}</small></td><td>{{money(v.amount_cents)}}</td><td class="receipt-status-cell"><div class="receipt-status-stack"><span class="sb-badge">{{receiptLabels[v.status]}}</span><small v-if="v.review_note">{{v.review_note}}</small></div></td><td>{{businessTime(v.created_at)}}<small>入账：{{businessTime(v.posted_at)}}</small></td><td><div class="sb-actions"><button @click="open(v,'history')">详情与历史</button><CustomerReceiptReviewAction :receipt="v" :finance="Boolean(finance)" :can-review="Boolean(canReview)" :actor-user-id="actor?.user_id" :require-distinct-reviewer="requireDistinctReviewer" :policy-ready="policyReady" @review="open(v,'review')"/><button v-if="canSubmit&&['needs_info','rejected'].includes(v.status)" @click="open(v,'resubmit')">补件重提</button></div></td></tr></tbody></table></div><div v-else class="sb-grid"><article v-for="v in items" :key="v.id" class="sb-record"><header><h3>{{v.customer_name}}</h3><span class="sb-badge">{{receiptLabels[v.status]}}</span></header><p>{{money(v.amount_cents)}} · {{channelLabels[v.channel]}}</p><small>{{v.receipt_no}} · {{purposeLabels[v.purpose]}}</small><p>{{v.review_note}}</p><small>入账：{{businessTime(v.posted_at)}}</small><div class="sb-actions"><button @click="open(v,'history')">详情与历史</button><CustomerReceiptReviewAction :receipt="v" :finance="Boolean(finance)" :can-review="Boolean(canReview)" :actor-user-id="actor?.user_id" :require-distinct-reviewer="requireDistinctReviewer" :policy-ready="policyReady" @review="open(v,'review')"/><button v-if="canSubmit&&['needs_info','rejected'].includes(v.status)" @click="open(v,'resubmit')">补件重提</button></div></article></div></template><PaginationBar v-if="!loading&&!error" v-model:page="page" :total="total" :total-pages="pages" :page-size="size"/></section>
<BusinessDialog v-if="mode" :title="mode==='submit'?'收款资料':mode==='review'?'财务审核':mode==='resubmit'?'补件重提':'收款详情'" :busy="saving" @close="mode=''"><CustomerReceiptForm v-if="mode==='submit'" :tenant-id="formTenant" @saved="mode='';notice='资料已提交，等待财务审核';load()" @cancel="mode=''"/><template v-else-if="target"><h3>{{target.customer_name}} · {{money(target.amount_cents)}}</h3><p>{{target.receipt_no}} · {{receiptLabels[target.status]}} · {{channelLabels[target.channel]}}</p><p>{{purposeLabels[target.purpose]}}；原流水 {{target.external_trade_no}}</p><div v-if="finance" class="sb-note"><p>付款方：{{target.payer_name}}；收款账户：{{target.receiving_account}}</p><p>凭据说明：{{target.evidence}}</p><p>原订单ID：{{target.order_id||'—'}}；支付记录ID：{{target.verified_payment_id||'—'}}；既有充值ID：{{target.existing_recharge_id||'—'}}</p></div><p v-if="formError" class="sb-error" role="alert">{{formError}}</p><form v-if="mode==='review'||mode==='resubmit'" class="sb-form" @submit.prevent="save"><label v-if="mode==='review'" class="sb-wide">处理结果<select v-model="action"><option value="post">核实到账并审核入账</option><option value="needs_info">要求补充资料</option><option value="reject">审核不通过</option></select></label><label class="sb-wide">{{mode==='resubmit'?'补充凭据材料':'对外审核说明'}}<textarea v-model="note" required :maxlength="mode==='resubmit'?2000:1000"/></label><label v-if="mode==='review'" class="sb-wide"><span><input v-model="confirmed" type="checkbox" required style="width:auto"/> 我已核对实际收款、金额和客户归属。{{ requireDistinctReviewer ? '按配置由不同审核人办理。' : '当前允许有权限人员兼岗，完整保留经办和审核记录。' }}</span></label><button class="primary sb-wide" type="submit" :disabled="saving||(mode==='review'&&(!confirmed||!policyReady||!canReview||(requireDistinctReviewer&&(target.requester_user_id===actor?.user_id||target.last_submitter_user_id===actor?.user_id))))">{{saving?'处理中…':'确认提交'}}</button></form><template v-else><CustomerReceiptReviewAction :receipt="target" :finance="Boolean(finance)" :can-review="Boolean(canReview)" :actor-user-id="actor?.user_id" :require-distinct-reviewer="requireDistinctReviewer" :policy-ready="policyReady" @review="open(target,'review')"/><BusinessHistory kind="receipt" :id="target.id"/></template></template></BusinessDialog></div></template>

<style scoped>
.customer-receipts-page {font-size:18px;line-height:1.45;--table-font-size:18px}
.customer-receipts-page :deep(button),.customer-receipts-page :deep(input),.customer-receipts-page :deep(select),.customer-receipts-page :deep(textarea) {font-size:18px;line-height:1.4}
.customer-receipts-page :deep(button) {min-height:38px;padding:6px 10px;border-radius:8px}
.customer-receipts-page h2 {font-size:24px}
.customer-receipts-page h3 {font-size:20px}
.customer-receipts-page .sb-table table th,.customer-receipts-page .sb-table table td {font-size:18px!important;line-height:1.45;padding:12px;vertical-align:top}
.customer-receipts-page .sb-table table td strong {font-size:18px!important;font-weight:600}
.customer-receipts-page .sb-table table td small {font-size:16px!important;line-height:1.4;margin-top:4px;max-width:300px;overflow-wrap:anywhere}
.customer-receipts-page .sb-badge {font-size:16px;padding:0 8px;line-height:26px;min-height:26px;box-sizing:border-box}
.customer-receipts-page .receipt-status-stack {display:flex;flex-direction:column;align-items:flex-start;gap:4px}
.customer-receipts-page .receipt-status-stack small {margin:0!important;text-align:left}
.customer-receipts-page .receipt-policy-link {font-size:16px;color:#326bd8;padding:6px 10px;border-radius:8px}
.customer-receipts-page .receipt-policy-link:hover {background:#edf5ff;box-shadow:0 0 0 3px #4285ff20}
.customer-receipts-page .sb-table table {min-width:1180px}
.customer-receipts-page .sb-table th:last-child,.customer-receipts-page .sb-table td:last-child {position:sticky;right:0;width:350px;min-width:350px;background:#f7faff;box-shadow:-4px 0 10px #3059900c;z-index:1}
.customer-receipts-page .sb-table th:last-child {z-index:2;background:#f1f6ff}
.customer-receipts-page .sb-table td:last-child .sb-actions {margin:0;align-items:flex-start;gap:8px}
.receipt-policy-status {display:flex;align-items:center;flex-wrap:wrap;gap:12px;font-size:16px;color:#607695}
.receipt-policy-status a {color:#2f65b5;text-decoration:none}
.receipt-policy-status a:hover {text-shadow:0 0 8px #4285ff55}
</style>

